import { npcAt, type PixelPosition } from './pixelTownLogic';
import { worldCell } from './proceduralWorld';

/**
 * Original LIVEIT districts. These are authored transport hubs in the same
 * deterministic infinite tile world, not copied maps or Pokémon assets.
 *
 * The street grid between them is generated by proceduralWorld.ts, so walking
 * and transit both land in the same persistent coordinate space.
 */
export const WORLD_REGIONS = [
  { id: 'bellweather', name: 'Bellweather Market', subtitle: 'Café · homes · market gardens', x: 11, y: 8, color: '#eac080' },
  { id: 'willowmere', name: 'Willowmere Campus', subtitle: 'University · library · student quarter', x: 264, y: 8, color: '#9fc8e2' },
  { id: 'quayside', name: 'North Quay', subtitle: 'Harbour · warehouses · waterfront', x: -248, y: 8, color: '#84c9d4' },
  { id: 'larkspur', name: 'Larkspur Heights', subtitle: 'Hill streets · trails · observatory', x: 8, y: -248, color: '#bad4a0' },
  { id: 'orchard', name: 'Sundown Orchard', subtitle: 'Farm markets · fields · countryside', x: 8, y: 264, color: '#e7c98c' },
  { id: 'foundry', name: 'Foundry Quarter', subtitle: 'Workshops · studios · industry', x: 264, y: 264, color: '#e2a89b' },
  { id: 'tideglass', name: 'Tideglass Coast', subtitle: 'Promenade · beach · fishing boats', x: -248, y: 264, color: '#81d3ca' },
  { id: 'oldtown', name: 'Lantern Old Town', subtitle: 'Theatre · stone lanes · late cafés', x: -248, y: -248, color: '#d6b4e4' },
  { id: 'cedarwood', name: 'Cedarwood Reserve', subtitle: 'Woodlands · nature paths · cabins', x: 264, y: -248, color: '#9ac99b' },
] as const;

export type WorldRegion = (typeof WORLD_REGIONS)[number];
export type RegionId = WorldRegion['id'];

/** Region selection uses fixed map coordinates, not camera render order. */
export function regionAt(x: number, y: number): WorldRegion {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return WORLD_REGIONS[0];
  let nearest: WorldRegion = WORLD_REGIONS[0];
  let best = Number.POSITIVE_INFINITY;
  for (const candidate of WORLD_REGIONS) {
    const distance = (x - candidate.x) ** 2 + (y - candidate.y) ** 2;
    if (distance < best) {
      best = distance;
      nearest = candidate;
    }
  }
  return nearest;
}

/**
 * Find a deterministic, actually walkable landing tile using the same
 * collision rules as player movement and saves. Never place a traveller
 * inside a wall, a locked door, or Amelia's canonical standing position.
 */
export function regionArrival(regionId: RegionId, seed: number): PixelPosition {
  const region = WORLD_REGIONS.find((item) => item.id === regionId);
  if (!region) throw new Error('Unknown region: ' + regionId);
  for (let radius = 0; radius <= 20; radius++) {
    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== radius) continue;
        const x = region.x + dx;
        const y = region.y + dy;
        if (worldCell('street', x, y, seed).solid) continue;
        const npc = npcAt('street');
        if (x === npc.x && y === npc.y) continue;
        return { place: 'street', x, y, facing: 'down' };
      }
    }
  }
  throw new Error('No safe arrival for ' + region.name);
}
